pub fn run_length_encode(s: &str) -> Vec<(char, usize)> {
    let mut result = Vec::new();
    let mut chars = s.chars();
    let Some(first) = chars.next() else { return result; };
    let mut cur_char = first;
    let mut cur_count = 1usize;
    for c in chars {
        if c == cur_char {
            cur_count += 1;
        } else {
            result.push((cur_char, cur_count));
            cur_char = c;
            cur_count = 1;
        }
    }
    result.push((cur_char, cur_count));
    result
}

