pub fn transpose_matrix(matrix: &[Vec<i32>]) -> Vec<Vec<i32>> {
    if matrix.is_empty() || matrix[0].is_empty() {
        return Vec::new();
    }
    let rows = matrix.len();
    let cols = matrix[0].len();
    let mut out = vec![vec![0i32; rows]; cols];
    for r in 0..rows {
        for c in 0..cols {
            out[c][r] = matrix[r][c];
        }
    }
    out
}
